function getCollateralValue(address pair, uint256 tokenAmount) public view returns (uint256) {
    (uint112 reserve0, uint112 reserve1,) = IUniswapV2Pair(pair).getReserves();
    // VULNERABILITY: Spot reserve ratio can be manipulated via flash swap
    uint256 price = (uint256(reserve1) * 1e18) / uint256(reserve0);
    return (tokenAmount * price) / 1e18;
}

function getLpValue(address lpToken, uint256 lpAmount) external view returns (uint256) {
    uint256 total = IERC20(lpToken).totalSupply();
    // VULNERABILITY: balanceOf(pair) can be manipulated by donating tokens
    uint256 balance0 = IERC20(token0).balanceOf(lpToken);
    return (lpAmount * balance0 * 2) / total;
}

function getAssetPrice(address pool) external view returns (uint256) {
    // VULNERABILITY: slot0 returns instantaneous spot price
    (uint160 sqrtPriceX96,,,,,,) = IUniswapV3Pool(pool).slot0();
    uint256 price = uint256(sqrtPriceX96) * uint256(sqrtPriceX96) * 1e18 >> 192;
    return price;
}

function getTwapPrice(address pool, uint32 twapInterval) public view returns (uint256) {
    require(twapInterval >= 1800, "interval too short"); // 30 min minimum
    uint32[] memory secondsAgos = new uint32[](2);
    secondsAgos[0] = twapInterval;
    secondsAgos[1] = 0;
    (int56[] memory tickCumulatives,) = IUniswapV3Pool(pool).observe(secondsAgos);
    int56 timeWeightedAverageTick = (tickCumulatives[1] - tickCumulatives[0]) / int56(uint56(twapInterval));
    return OracleLibrary.getQuoteAtTick(int24(timeWeightedAverageTick), 1e18, token0, token1);
}

function getChainlinkPrice(address feed) public view returns (uint256) {
    (
        uint80 roundId,
        int256 price,
        ,
        uint256 updatedAt,
        uint80 answeredInRound
    ) = AggregatorV3Interface(feed).latestRoundData();
    require(price > 0, "invalid price");
    require(updatedAt >= block.timestamp - 3600, "stale price");
    require(answeredInRound >= roundId, "stale round");
    return uint256(price);
}

function previewQuote(uint256 amountIn) external view returns (uint256 estimatedOut) {
    // For UI display only — settlement uses Chainlink in executeTrade()
    (uint112 r0, uint112 r1,) = pair.getReserves();
    return (amountIn * uint256(r1)) / uint256(r0);
}

function getFairLpPrice(address pair) public view returns (uint256) {
    (uint112 r0, uint112 r1,) = IUniswapV2Pair(pair).getReserves();
    uint256 k = uint256(r0) * uint256(r1);
    uint256 p0 = getChainlinkPrice(token0);
    uint256 p1 = getChainlinkPrice(token1);
    // Alpha Finance fair LP formula: 2 * sqrt(k) * sqrt(p0 * p1) / totalSupply
    return (2 * Math.sqrt(k) * Math.sqrt(p0 * p1)) / IUniswapV2Pair(pair).totalSupply();
}

