function calculateBorrowPower(address user) external view returns (uint256 totalPower) {
    for (uint i = 0; i < userCollateral[user].length; i++) {
        address token = userCollateral[user][i].token;
        uint256 price = IOracle(oracle).getPrice(token); // Oracle implementation unknown
        totalPower += userCollateral[user][i].amount * price;
    }
}

