function getCurveLpPrice(address curvePool) external view returns (uint256) {
    uint256 vp = ICurvePool(curvePool).get_virtual_price();
    uint256 minPrice = IOracle(oracle).getMinAssetPrice(curvePool);
    return (vp * minPrice) / 1e18;
}

function getSharePrice(address vault) public view returns (uint256) {
    uint256 totalShares = IERC4626(vault).totalSupply();
    if (totalShares == 0) return 1e18;
    // VULNERABILITY: totalAssets() can be inflated by direct transfer
    return (IERC4626(vault).totalAssets() * 1e18) / totalShares;
}

