function calculateHealth(address account) external view returns (int256 health) {
    for (uint i = 0; i < markets.length; i++) {
        uint256 spotPrice = ISpotMarket(markets[i]).getBestBid(); // Spot market with low depth
        health += deposits[account][markets[i]] * int256(spotPrice);
        health -= borrows[account][markets[i]] * int256(spotPrice);
    }
}

function getGuardedPrice(address token) external view returns (uint256) {
    uint256 clPrice = getChainlinkPrice(token);
    uint256 twapPrice = getUniswapV3Twap(token, 1800);
    // Circuit breaker: revert if oracles diverge > 2%
    uint256 diff = clPrice > twapPrice ? clPrice - twapPrice : twapPrice - clPrice;
    require((diff * 100) / clPrice <= 2, "oracle divergence exceeds 2%");
    // Conservative: use lowest price for collateral evaluation
    return clPrice < twapPrice ? clPrice : twapPrice;
}

function getPythPrice(bytes32 priceId) public view returns (uint256) {
    PythStructs.Price memory pythPrice = IPyth(pythContract).getPriceUnsafe(priceId);
    // Unsafe: getPriceUnsafe called without fee-paid getPriceNoOlderThan
    require(pythPrice.price > 0);
    return uint256(uint64(pythPrice.price));
}

function exchangeRate(address pool) public view returns (uint256) {
    uint256 totalShares = ILendingPool(pool).totalShares();
    if (totalShares == 0) return 1e18;
    // VULNERABILITY: pool totalUnderlying includes direct donations in current block
    uint256 totalUnderlying = IERC20(underlying).balanceOf(pool);
    return (totalUnderlying * 1e18) / totalShares;
}
